# reset-local-data.ps1 – Reset local Docker data (Windows PowerShell)  # ---------------------------------------------------------------  # WARNING: This removes all persisted data (Postgres volume).  # The script asks for typed confirmation before proceeding.   Write-Host 'THIS WILL REMOVE ALL LOCAL DATABASE DATA (Postgres volume).' -ForegroundColor Yellow  Write-Host 'To continue, type the word RESET and press Enter.' -ForegroundColor Yellow  $confirmation = Read-Host  if ($confirmation -ne 'RESET') { Write-Host 'Confirmation not received. Aborting.' -ForegroundColor Red; exit 1 }  $localEnv = Join-Path -Path $PSScriptRoot '..' '.env.local'  if (Test-Path $localEnv) { docker compose --env-file $localEnv down -v  } else { docker compose down -v }  if ($LASTEXITCODE -eq 0) { Write-Host 'All containers stopped and volumes removed.' -ForegroundColor Green } else { Write-Host 'docker compose down -v returned an error.' -ForegroundColor Red }